import java.util.Scanner;
public class JCheckAge1 {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil al-ism wal-umr, mufasilan bi-nuqTa (:)");
		String name = scan.next();
		JCheckAge1 jca = new JCheckAge1();
		jca.checkAge(name);
	}
	// Khatwa 1: Tareef al-method allati tata'amal ma'a al-silsila al-modkhula
	public void checkAge(String s) {
		// Khatwa 1.1: Qasim al-silsila al-mawdooha ila al-ism wal-umr
		String[] lst = s.split(":");
		// Khatwa 1.2: Huwt al-kod alladhi qad yurmee istithna' fi block al-try
		try {
			String name = lst[0];
			int age = Integer.parseInt(lst[1]);
			if ( age >= 13 && age <= 19 ) {           
				System.out.println(name + " huwa muraaHiq.");
			} else {          
				System.out.println(name + " laysa muraaHiqan.");
			}
		}
		// Khatwa 1.3: Ta'amal ma'a jami' al-istithna'at al-muhtamalah alati qad turma fi block al-try
		catch ( ArrayIndexOutOfBoundsException ex ) {
			System.out.println("Khata! Afruq al-ism wal-umr bi-nuqTa (:)");
		} catch ( NumberFormatException ex) {
			System.out.println("Khata! Al-umr yajibu an yakun raqman kamilan.");
		}
	}
}
